// Fill DSM holes by successive over-relaxation, starting from the mean of the valid posts.
export function fillHoles(heights, width, height, tolerance = 1e-4) {
  const z = Float32Array.from(heights);
  const holes = [];
  let sum = 0;
  let count = 0;
  for (let i = 0; i < z.length; i += 1) {
    if (Number.isNaN(z[i])) holes.push(i);
    else {
      sum += z[i];
      count += 1;
    }
  }
  for (const i of holes) z[i] = sum / count;
  const omega = 1.8;
  for (let sweep = 0; sweep < 800; sweep += 1) {
    let change = 0;
    for (const i of holes) {
      const x = i % width;
      const y = (i - x) / width;
      const left = z[x > 0 ? i - 1 : i];
      const right = z[x < width - 1 ? i + 1 : i];
      const up = z[y > 0 ? i - width : i];
      const down = z[y < height - 1 ? i + width : i];
      const next = z[i] + omega * ((left + right + up + down) / 4 - z[i]);
      change = Math.max(change, Math.abs(next - z[i]));
      z[i] = next;
    }
    if (change < tolerance) break;
  }
  return z;
}
